import { MigrateUpArgs, MigrateDownArgs, sql } from '@payloadcms/db-postgres'

// Retires the StudentGroups collection (ADR-0021): Clubs and their Club
// Profiles now live in the Portal. Deploys run migrations automatically, so the
// rows are first kept in student_groups_archive, with each logo's media file
// name, for the one-time copy into Portal Club Profiles
// (scripts/export-student-groups.ts). Drop the archive once that copy is done.
//
// Generated by `payload migrate:create`, then reordered: the generated SQL
// dropped student_groups with CASCADE before dropping the constraint that
// referenced it, which fails because CASCADE has already removed it.
export async function up({ db, payload, req }: MigrateUpArgs): Promise<void> {
  await db.execute(sql`
  CREATE TABLE "student_groups_archive" AS
    SELECT
      g."id", g."name", g."short_name", g."slug", g."type"::text AS "type",
      g."contact_email", g."instagram", g."website", g."is_active",
      g."description", m."filename" AS "logo_filename",
      now() AS "archived_at"
    FROM "student_groups" g
    LEFT JOIN "media" m ON m."id" = g."logo_id";
  DELETE FROM "payload_locked_documents" WHERE "id" IN (
    SELECT "parent_id" FROM "payload_locked_documents_rels" WHERE "student_groups_id" IS NOT NULL
  );
  ALTER TABLE "payload_locked_documents_rels" DROP CONSTRAINT "payload_locked_documents_rels_student_groups_fk";
  DROP INDEX "payload_locked_documents_rels_student_groups_id_idx";
  ALTER TABLE "payload_locked_documents_rels" DROP COLUMN "student_groups_id";
  ALTER TABLE "student_groups" DISABLE ROW LEVEL SECURITY;
  DROP TABLE "student_groups" CASCADE;
  DROP TYPE "public"."enum_student_groups_type";`)
}

